// Spanish edition of the glossary and Know Your Rights scenarios.
// Terms are alphabetized by their Spanish name; the English legal term
// appears in parentheses because U.S. legal proceedings use English.
// Case reference keys stay in English so inline case links keep working.

export const glossary = [
  // === A ===
  { term: "Abogado defensor (Counsel)", definition: "Un abogado. La 6.ª Enmienda garantiza el derecho a la 'asistencia de un abogado': usted tiene derecho a un abogado en casos penales, y si no puede pagarlo y enfrenta cárcel, el tribunal debe proporcionarle uno gratis." },
  { term: "Absolución (Acquittal)", definition: "Un veredicto de no culpable. Una vez absuelto, la prohibición del doble juicio impide que le juzguen de nuevo por el mismo delito." },
  { term: "Activismo judicial (Judicial Activism)", definition: "Cuando se percibe que los tribunales toman decisiones políticas en lugar de solo interpretar la ley. El término suele usarlo quien está en desacuerdo con un fallo." },
  { term: "Acto manifiesto (Overt Act)", definition: "Una acción abierta y observable. La traición requiere prueba de un acto manifiesto: solo pensar en traicionar al país no basta. Dos testigos deben atestiguar el mismo acto." },
  { term: "Acuerdo de culpabilidad (Plea Bargain)", definition: "Un acuerdo donde el acusado se declara culpable, a menudo de un cargo menor, a cambio de una sentencia más leve. Más del 90% de las condenas penales en Estados Unidos provienen de declaraciones de culpabilidad y no de juicios." },
  { term: "Acusación formal (Indictment)", definition: "Una acusación formal de un delito, emitida por un gran jurado. Requerida para delitos federales graves según la 5.ª Enmienda." },
  { term: "Acusado (Defendant)", definition: "La persona o entidad acusada en un caso legal. En casos penales, es la persona imputada de un delito. En casos civiles, es la persona demandada." },
  { term: "Adhesión (Adherence)", definition: "En el contexto de la traición, 'adherirse a' los enemigos significa darles lealtad o apoyo. La Constitución define la traición como hacer la guerra contra EE. UU. o adherirse a sus enemigos." },
  { term: "Agravio (Grievance)", definition: "Una queja u objeción. La 1.ª Enmienda protege su derecho a 'presentar peticiones al gobierno para la reparación de agravios', es decir, quejarse formalmente y exigir que se corrijan los males." },
  { term: "Al amparo de la ley (Color of Law)", definition: "Actuar con apariencia de autoridad legal. Cuando un policía o funcionario viola sus derechos estando de servicio, actúa 'al amparo de la ley', lo que puede fundar una demanda federal de derechos civiles." },
  { term: "Alojamiento de soldados (Quartering)", definition: "Hospedar soldados en casas privadas. La 3.ª Enmienda prohíbe alojar tropas en una casa sin el consentimiento del dueño en tiempos de paz, y en tiempos de guerra solo lo permite según lo disponga la ley." },
  { term: "Amicus Curiae", definition: "Latín para 'amigo del tribunal.' Una persona u organización ajena a un caso que presenta un escrito con información o argumentos para ayudar al tribunal a decidir. Común en casos de la Corte Suprema." },
  { term: "Anulación estatal (Nullification)", definition: "La idea (rechazada) de que los estados pueden declarar inconstitucionales las leyes federales y negarse a aplicarlas. La Corte Suprema la ha declarado inválida consistentemente." },
  { term: "Anular (Vacate)", definition: "Invalidar o cancelar una decisión judicial. Un tribunal superior puede anular el fallo de uno inferior, borrándolo como si nunca hubiera existido." },
  { term: "Anular un veto (Override)", definition: "Dejar sin efecto el veto presidencial. El Congreso puede anular un veto con el voto de 2/3 de ambas cámaras, convirtiendo el proyecto en ley pese a la objeción del Presidente." },
  { term: "Aplazamiento (Continuance)", definition: "La postergación de un procedimiento judicial a una fecha posterior. Demasiados aplazamientos pueden violar el derecho a un juicio rápido." },
  { term: "Arancel (Tariff)", definition: "Un impuesto sobre bienes importados, que se cobra cuando los bienes entran al país. La Constitución otorga este poder al Congreso y llama a estos impuestos 'duties' e 'imposts' (derechos de aduana e impuestos aduaneros). La Corte ha señalado que, cuando el Congreso delega su poder arancelario en una ley, lo hace de forma expresa y con límites estrictos. En Learning Resources v. Trump (2026), la Corte sostuvo que la Ley de Poderes Económicos de Emergencia Internacional (IEEPA), que permite al Presidente 'regular . . . la importación' durante una emergencia declarada, no autoriza aranceles." },
  { term: "Arbitraje (Arbitration)", definition: "Un proceso privado donde las disputas las resuelve un tercero neutral en lugar de un tribunal. Muchos contratos exigen arbitraje obligatorio, lo que implica renunciar a su derecho a un juicio con jurado." },
  { term: "Armas (Arms)", definition: "La 2.ª Enmienda protege el derecho a poseer y portar armas. Los tribunales han debatido qué tipos de armas cubre." },
  { term: "Asilo (Asylum)", definition: "Protección para una persona que está en Estados Unidos, incluso alguien que acaba de cruzar la frontera, y que teme ser perseguida en su país por su raza, religión, nacionalidad, opinión política o pertenencia a un grupo social determinado. En general, la solicitud debe presentarse dentro del año siguiente a la llegada. En Mullin v. Al Otro Lado (2026), la Corte sostuvo que una persona que todavía está en México no ha 'llegado a' Estados Unidos, así que los agentes no tienen que inspeccionarla ni permitirle solicitar asilo hasta que cruce la frontera." },
  { term: "Audiencia de fianza (Bond Hearing)", definition: "Una audiencia ante un juez de inmigración para decidir si una persona no ciudadana detenida puede ser liberada mientras continúa su caso, y cuánto debe pagar de fianza. Algunas personas están sujetas a detención obligatoria según la ley de inmigración y pueden no tener derecho a esta audiencia." },
  { term: "Auto judicial (Writ)", definition: "Una orden judicial formal y escrita que manda hacer o dejar de hacer algo. Tipos: habeas corpus, mandamus y certiorari." },
  { term: "Autocontención judicial (Judicial Restraint)", definition: "La filosofía de que los tribunales deben evitar anular leyes salvo clara inconstitucionalidad y deferir a las ramas electas cuando sea posible." },
  { term: "Autoincriminación (Self-Incrimination)", definition: "Ser obligado a dar testimonio o pruebas que podrían usarse en su contra en un caso penal. La 5.ª Enmienda lo prohíbe; de ahí viene 'acogerse a la Quinta.'" },
  { term: "Autorización previa (Preclearance)", definition: "El requisito de que ciertos estados obtengan aprobación federal antes de cambiar sus leyes electorales. Parte de la Ley de Derecho al Voto, terminó en la práctica cuando la Corte Suprema anuló su fórmula en Shelby County v. Holder." },
  { term: "Ayuda y auxilio (Aid and Comfort)", definition: "Ayuda o apoyo dado a un enemigo. Según la Constitución, dar 'ayuda y auxilio' a los enemigos de Estados Unidos es parte de la definición legal de traición." },

  // === B ===
  { term: "Bien regulada (Well-Regulated)", definition: "En el uso del siglo XVIII, 'bien regulada' solía significar debidamente entrenada, disciplinada o en buen funcionamiento. En District of Columbia v. Heller (2008), la Corte interpretó la 'milicia bien regulada' de la 2.ª Enmienda como una milicia debidamente entrenada y disciplinada." },
  { term: "Bienestar general (General Welfare)", definition: "El bienestar del público en su conjunto. El Preámbulo lista 'promover el bienestar general' como propósito del gobierno. El Congreso puede gravar y gastar para promoverlo." },
  { term: "Buena fe (Good Faith)", definition: "Intención honesta sin conocimiento de irregularidad. La 'excepción de buena fe' a la regla de exclusión permite usar evidencia si la policía creía razonablemente que su registro era legal." },

  // === C ===
  { term: "Cacheo (Frisk)", definition: "Una revisión rápida, palpando la ropa exterior de una persona, para buscar armas. Según Terry v. Ohio (1968), la policía solo puede cachear si cree razonablemente que la persona está armada y es peligrosa; no es un registro completo en busca de evidencia." },
  { term: "Carga de la prueba (Burden of Proof)", definition: "La obligación de probar su caso. En juicios penales, la fiscalía debe probar la culpabilidad 'más allá de toda duda razonable.' En casos civiles el estándar es menor: 'preponderancia de la evidencia' (más probable que no)." },
  { term: "Carta constitutiva (Charter)", definition: "Un documento que otorga derechos y poderes de gobierno. Muchas colonias se gobernaban por cartas reales, y la Declaración acusa al Rey de 'abolir nuestras cartas', como hizo el Parlamento cuando modificó la carta de Massachusetts en 1774." },
  { term: "Carta de Derechos (Bill of Rights)", definition: "Las primeras 10 enmiendas de la Constitución, ratificadas en 1791. Detallan sus derechos personales más fundamentales frente a la interferencia del gobierno." },
  { term: "Castigo cruel e inusual (Cruel and Unusual Punishment)", definition: "Castigo bárbaro, torturante o groseramente desproporcionado al delito. Prohibido por la 8.ª Enmienda. Lo que cuenta como 'cruel e inusual' evoluciona con el tiempo." },
  { term: "Causa probable (Probable Cause)", definition: "Motivos razonables para creer que se ha cometido un delito. Requerida para arrestos y órdenes de registro según la 4.ª Enmienda. Más que una corazonada, menos que prueba plena." },
  { term: "Censura (Censorship)", definition: "Cuando el gobierno suprime expresión, prensa o información. La 1.ª Enmienda generalmente la prohíbe, especialmente la 'censura previa', que bloquea la publicación antes de que ocurra." },
  { term: "Censura previa (Prior Restraint)", definition: "Censura gubernamental que bloquea la expresión o publicación antes de que suceda. Los tribunales exigen un estándar altísimo, haciéndola casi siempre inconstitucional." },
  { term: "Certiorari", definition: "Una orden de un tribunal superior para revisar la decisión de uno inferior. La Corte Suprema concede el 'cert' a los casos que elige atender: en los últimos años, unos 60 al año de entre unas 4000 solicitudes." },
  { term: "Circunstancias apremiantes (Exigent Circumstances)", definition: "Situaciones de emergencia que permiten a la policía actuar sin orden judicial. Ejemplos: alguien gritando por ayuda dentro de una casa o evidencia a punto de destruirse. Para entrar a una vivienda a ayudar a alguien, la policía necesita una base objetivamente razonable para creer que una persona adentro está gravemente herida o a punto de estarlo; no se requiere causa probable (Case v. Montana (2026))." },
  { term: "Citación judicial (Subpoena)", definition: "Una orden legal que exige comparecer ante el tribunal o entregar documentos. Del latín 'sub poena', 'bajo pena.' Ignorarla puede constituir desacato." },
  { term: "Citación obligatoria (Compulsory Process)", definition: "El poder de obligar a testigos a comparecer y declarar. La 6.ª Enmienda garantiza al acusado el derecho de traer testigos a su favor." },
  { term: "Ciudadanía (Citizenship)", definition: "La pertenencia legal plena a la nación. Los ciudadanos pueden votar en elecciones federales a partir de los 18 años, tener pasaporte estadounidense y no pueden ser deportados. Una persona es ciudadana por nacer en Estados Unidos (14.ª Enmienda), por nacer en el extranjero de padre o madre ciudadanos (según la ley federal) o por naturalización." },
  { term: "Ciudadanía por nacimiento (Birthright Citizenship)", definition: "La regla de que las personas nacidas en suelo estadounidense y 'sujetas a su jurisdicción' son ciudadanas desde su nacimiento, según la Cláusula de Ciudadanía de la 14.ª Enmienda. En United States v. Wong Kim Ark (1898), la Corte Suprema la aplicó a un hombre nacido en San Francisco de padres chinos que residían en el país; las excepciones reconocidas son estrechas, como los hijos de diplomáticos extranjeros. En Trump v. Barbara (2026), la Corte reafirmó Wong Kim Ark y sostuvo que los hijos nacidos aquí de padres que están en el país de manera ilegal o temporal son ciudadanos desde su nacimiento, en contra de una orden ejecutiva de 2025 que decía lo contrario. Como esa decisión se basa en la propia 14.ª Enmienda, no puede cambiarse mediante una orden ejecutiva ni una ley ordinaria del Congreso." },
  { term: "Cláusula (Clause)", definition: "Una sección o disposición específica dentro de un documento legal. La Constitución contiene muchas cláusulas con nombre, como la de Comercio, la de Supremacía y la del Debido Proceso." },
  { term: "Cláusula de Aplicación (Enforcement Clause)", definition: "Una sección presente en varias enmiendas, entre ellas la 13.ª, la 14.ª, la 15.ª, la 19.ª, la 24.ª y la 26.ª, que da al Congreso el poder de hacer cumplir la enmienda 'mediante legislación apropiada.' Según City of Boerne v. Flores (1997), las leyes aprobadas con el poder de aplicación de la 14.ª Enmienda deben ser 'congruentes y proporcionales' a las violaciones que buscan corregir." },
  { term: "Cláusula de Comercio (Commerce Clause)", definition: "El Artículo I, Sección 8 da al Congreso el poder de regular el comercio con naciones extranjeras, entre los estados y con las tribus indígenas. El poder sobre el comercio entre estados se ha interpretado con gran amplitud para justificar muchas leyes federales, aunque United States v. Lopez (1995) fijó algunos límites." },
  { term: "Cláusula de Confrontación (Confrontation Clause)", definition: "La parte de la 6.ª Enmienda que le da derecho a encarar a sus acusadores en el tribunal y contrainterrogar a los testigos en su contra. No se permiten testigos secretos. Un tribunal solo puede proteger a un testigo menor con una pantalla después de escuchar pruebas y determinar que es necesario en ese caso concreto; una ley estatal que exige pantallas no basta (Pitts v. Mississippi (2025))." },
  { term: "Cláusula de Discurso o Debate (Speech or Debate Clause)", definition: "El Artículo I, Sección 6, que protege a los miembros del Congreso de ser demandados o procesados por su labor legislativa, como discursos, votos e informes de comité. En Gravel v. United States (1972), la Corte sostuvo que la protección se extiende a sus asistentes, pero no a actividades fuera del proceso legislativo." },
  { term: "Cláusula de Elecciones (Elections Clause)", definition: "El Artículo I, Sección 4, que permite a cada legislatura estatal fijar 'la fecha, el lugar y la manera' de las elecciones al Congreso, y permite al Congreso cambiar esas reglas. En Moore v. Harper (2023), la Corte Suprema sostuvo que los tribunales estatales aún pueden revisar esas leyes electorales conforme a la constitución del estado, siempre que no excedan los límites ordinarios de la revisión judicial." },
  { term: "Cláusula de Esclavos Fugitivos (Fugitive Slave Clause)", definition: "El Artículo IV, Sección 2, Cláusula 3, que exigía devolver a las personas esclavizadas que huían a otro estado. En Prigg v. Pennsylvania (1842), la Corte anuló una ley estatal que dificultaba su recaptura. La 13.ª Enmienda (1865) dejó la cláusula sin efecto al abolir la esclavitud." },
  { term: "Cláusula de Establecimiento (Establishment Clause)", definition: "La parte de la 1.ª Enmienda que dice que el gobierno no puede crear ni favorecer una religión oficial." },
  { term: "Cláusula de Fiel Ejecución (Take Care Clause)", definition: "El requisito del Artículo II, Sección 3 de que el Presidente 'cuide de que las leyes se ejecuten fielmente.' Hace de la aplicación de la ley federal un deber. En Kendall v. United States ex rel. Stokes (1838), la Corte rechazó la idea de que este deber permita al Presidente prohibir a los funcionarios cumplir deberes fijados por el Congreso." },
  { term: "Cláusula de Garantía (Guarantee Clause)", definition: "El Artículo IV, Sección 4, en el que Estados Unidos garantiza a cada estado una forma republicana de gobierno y protección contra invasiones y violencia interna. En Luther v. Borden (1849), la Corte trató el cumplimiento de esta garantía como una cuestión política del Congreso y del Presidente, no de los tribunales." },
  { term: "Cláusula de Incompatibilidad (Incompatibility Clause)", definition: "Parte del Artículo I, Sección 6, que prohíbe a quien ocupa un cargo federal ser miembro del Congreso al mismo tiempo. Un congresista nombrado al Gabinete debe renunciar primero a su escaño, lo que mantiene separados los poderes legislativo y ejecutivo." },
  { term: "Cláusula de Inhabilitación (Disqualification Clause)", definition: "La Sección 3 de la 14.ª Enmienda, que prohíbe ocupar cargos a quien juró como funcionario apoyar la Constitución y luego participó en una insurrección o rebelión, o dio ayuda o auxilio a sus enemigos. El Congreso puede levantar la prohibición con el voto de dos tercios de cada cámara. En Trump v. Anderson (2024), la Corte sostuvo que los estados no pueden aplicarla contra candidatos a cargos federales; esa facultad corresponde al Congreso." },
  { term: "Cláusula de Libre Ejercicio (Free Exercise Clause)", definition: "La parte de la 1.ª Enmienda que dice que el gobierno no puede prohibirle practicar su religión. Las leyes neutrales que aplican a todos normalmente no la violan (Employment Division v. Smith (1990)), pero hay excepciones. En Mahmoud v. Taylor (2025), la Corte sostuvo que la negativa de una junta escolar a avisar a los padres y permitirles excusar a sus hijos de ciertas lecciones con libros de cuentos interfería sustancialmente con la formación religiosa de los niños y exigía un escrutinio estricto." },
  { term: "Cláusula de Origen (Origination Clause)", definition: "El Artículo I, Sección 7, que exige que los proyectos de ley para recaudar ingresos (impuestos) se presenten primero en la Cámara de Representantes. El Senado puede proponer o aprobar enmiendas, como en otros proyectos." },
  { term: "Cláusula de Propiedad (Property Clause)", definition: "Parte del Artículo IV, Sección 3, que da al Congreso el poder de dictar todas las reglas necesarias sobre las tierras y demás bienes de Estados Unidos, incluidos las tierras federales, los parques nacionales y los territorios estadounidenses." },
  { term: "Cláusula de Supremacía (Supremacy Clause)", definition: "El Artículo VI establece la Constitución y la ley federal válida como 'la ley suprema del país.' Las leyes estatales que las contradicen quedan sin efecto." },
  { term: "Cláusula elástica (Elastic Clause)", definition: "Otro nombre de la Cláusula Necesaria y Adecuada. Permite al Congreso aprobar leyes 'necesarias y adecuadas' para ejercer sus poderes, 'estirando' la autoridad federal más allá de lo explícitamente listado." },
  { term: "Cláusula Necesaria y Adecuada (Necessary and Proper Clause)", definition: "El Artículo I, Sección 8 permite al Congreso aprobar cualquier ley 'necesaria y adecuada' para ejercer sus poderes. También llamada 'cláusula elástica' porque estira el poder federal." },
  { term: "Coacción (Coercion)", definition: "Forzar a alguien mediante amenazas, presión o intimidación. Las confesiones obtenidas por coacción son inadmisibles, y la coacción gubernamental a empresas privadas para censurar puede violar la 1.ª Enmienda." },
  { term: "Colegio Electoral (Electoral College)", definition: "El sistema para elegir al Presidente. Cada estado recibe electores según su número de representantes más senadores, y Washington D. C. recibe tres según la 23.ª Enmienda. Un candidato necesita 270 de los 538 votos electorales para ganar." },
  { term: "Comandante en jefe (Commander in Chief)", definition: "El rol del Presidente como máxima autoridad militar. El Presidente comanda las fuerzas armadas pero no puede declarar la guerra: solo el Congreso puede." },
  { term: "Compensación justa (Just Compensation)", definition: "Pago justo. La 5.ª Enmienda exige que el gobierno pague una compensación justa cuando toma propiedad privada por expropiación. Qué es 'justo' suele disputarse. Cuando el gobierno vende una propiedad por impuestos impagos, al dueño se le debe el excedente, medido por el precio de la subasta y no por el valor de mercado, al menos cuando la venta se realiza de manera justa (Pung v. Isabella County (2026))." },
  { term: "Condena (Conviction)", definition: "La determinación formal de que una persona es culpable de un delito. Puede ocurrir por veredicto de culpabilidad en juicio o por declaración de culpabilidad." },
  { term: "Confederación (Confederation)", definition: "Una alianza laxa de estados independientes. Estados Unidos fue originalmente una confederación bajo los Artículos de la Confederación antes de que la Constitución creara un gobierno federal más fuerte." },
  { term: "Conferido (Vested)", definition: "Otorgado o depositado en alguien. 'Todos los poderes legislativos aquí otorgados serán conferidos a un Congreso' significa que la autoridad de legislar queda en manos del Congreso." },
  { term: "Confirmar (Affirm)", definition: "Cuando un tribunal superior está de acuerdo con la decisión de uno inferior y la deja en pie. Lo contrario de 'revocar.'" },
  { term: "Consanguinidad (Consanguinity)", definition: "Parentesco de sangre o de ascendencia común. La Declaración dice que el pueblo británico había sido 'sordo a la voz de la justicia y de la consanguinidad': ignoró los lazos familiares que compartía con los colonos." },
  { term: "Consentimiento de los gobernados (Consent of the Governed)", definition: "La idea de que la autoridad del gobierno proviene del acuerdo del pueblo a ser gobernado. Proviene de la Declaración de Independencia." },
  { term: "Contrainterrogar (Cross-Examine)", definition: "Interrogar a un testigo llamado por la otra parte. La 6.ª Enmienda garantiza su derecho a contrainterrogar a los testigos que declaran en su contra." },
  { term: "Corrupción de sangre (Corruption of Blood)", definition: "Un castigo antiguo donde la familia del traidor condenado también perdía derechos y propiedades. La Constitución lo prohíbe expresamente: no pueden castigarle por el delito de un familiar." },
  { term: "Cuestión política (Political Question)", definition: "Un asunto que los tribunales se niegan a decidir porque está asignado a otra rama del gobierno. Por ejemplo, no revisan cómo el Senado conduce los juicios políticos." },

  // === D ===
  { term: "Debido proceso (Due Process)", definition: "El gobierno debe seguir procedimientos justos antes de quitarle la vida, la libertad o la propiedad. Hay dos tipos: procesal (proceso justo) y sustantivo (leyes justas)." },
  { term: "Debido proceso procesal (Procedural Due Process)", definition: "El requisito de que el gobierno siga procedimientos justos antes de privarle de vida, libertad o propiedad. Implica saber de qué se le acusa y tener oportunidad de ser escuchado." },
  { term: "Debido proceso sustantivo (Substantive Due Process)", definition: "El principio de que ciertos derechos son tan fundamentales que ningún proceso legal basta para quitarlos. Los tribunales lo usan para proteger derechos como la privacidad, el matrimonio y la familia, que no están explícitos en la Constitución. En Dobbs v. Jackson Women's Health Organization (2022), la Corte sostuvo que el aborto no es uno de esos derechos y subrayó que los derechos no enumerados deben estar profundamente arraigados en la historia y la tradición del país." },
  { term: "Declaración jurada (Deposition)", definition: "El testimonio jurado de un testigo fuera del tribunal, tomado antes del juicio como parte del descubrimiento de pruebas. El testigo responde bajo juramento y se levanta acta." },
  { term: "Decomiso (Forfeiture)", definition: "La pérdida de propiedad como sanción. El decomiso civil permite al gobierno tomar propiedad sospechosa de estar vinculada a un delito, a menudo sin condena penal." },
  { term: "Decomiso civil de bienes (Civil Asset Forfeiture)", definition: "Cuando el gobierno confisca su propiedad (dinero, auto, casa) por sospecha de vínculo con un delito, sin necesariamente acusarle. La propiedad es la 'acusada', y el dueño a menudo debe acudir a los tribunales para recuperarla, a veces probando que no sabía de su uso ilegal ni lo consintió." },
  { term: "Decreto por consentimiento (Consent Decree)", definition: "Un acuerdo aprobado por un tribunal para resolver una demanda. Común cuando el gobierno resuelve casos de derechos civiles: el demandado acepta cambios sin admitir culpa." },
  { term: "Defensor público (Public Defender)", definition: "Un abogado pagado por el gobierno para representar a personas acusadas de delitos que no pueden pagar uno. El derecho viene de la 6.ª Enmienda según Gideon v. Wainwright (1963) y cubre todo caso que termine en una pena de cárcel. En los tribunales de inmigración no hay defensores públicos." },
  { term: "Delegar (Delegate)", definition: "Transferir poder o autoridad a otro. El Congreso a menudo delega en las agencias federales el poder de dictar reglas; sus defensores dicen que así los expertos manejan los detalles, y sus críticos, que se da demasiado poder a funcionarios no electos." },
  { term: "Deliberación (Deliberation)", definition: "El proceso de discusión y consideración cuidadosa. Un jurado delibera en privado para alcanzar un veredicto tras escuchar toda la evidencia." },
  { term: "Delito capital (Capital Crime)", definition: "Un delito castigable con la muerte. La 5.ª Enmienda exige acusación de un gran jurado para delitos capitales en casos federales." },
  { term: "Delito grave (Felony)", definition: "Un delito serio castigable con más de un año de prisión. Ejemplos: homicidio, robo con violencia y narcotráfico. Contrasta con los delitos menores." },
  { term: "Delito infame (Infamous Crime)", definition: "Un delito serio con castigo significativo y estigma social. La 5.ª Enmienda exige acusación de gran jurado para delitos 'capitales o infames.'" },
  { term: "Delito menor (Misdemeanor)", definition: "Un delito menos grave castigable con hasta un año de cárcel, multa o ambos. Ejemplos: hurto menor, agresión simple, allanamiento. Más serio que una infracción, menos que un delito grave." },
  { term: "Demanda Bivens (Bivens Claim)", definition: "Una demanda por daños y perjuicios contra un agente federal por violar sus derechos constitucionales, llamada así por Bivens v. Six Unknown Named Agents (1971). La Corte Suprema se ha negado a extender Bivens a situaciones nuevas, y desde Egbert v. Boule (2022) estas demandas son muy difíciles de presentar fuera de los hechos limitados de los casos originales. En Goldey v. Fields (2025), la Corte también se negó a extender Bivens a las demandas de presos federales contra funcionarios de prisiones por uso excesivo de la fuerza." },
  { term: "Demanda colectiva (Class Action)", definition: "Una demanda presentada por una o más personas en nombre de un grupo mayor que sufrió el mismo daño. Por ejemplo, todos los clientes cobrados de más por una empresa demandando juntos. Las demandas colectivas también pueden impugnar políticas del gobierno en nombre de todas las personas afectadas. Trump v. CASA (2025) limitó las medidas cautelares universales, pero señaló que esta vía sigue abierta, y en el caso que llegó a ser Trump v. Barbara (2026), un tribunal federal certificó provisionalmente una clase nacional de niños para impugnar la orden sobre la ciudadanía por nacimiento." },
  { term: "Demandante (Plaintiff)", definition: "Quien presenta una demanda. En casos civiles, el demandante pide indemnización u otro remedio. En casos penales, el gobierno (no un particular) presenta los cargos." },
  { term: "Denunciante (Whistleblower)", definition: "Una persona que reporta actividad ilegal o no ética dentro de una organización, especialmente una agencia gubernamental. Varias leyes protegen a los denunciantes contra represalias." },
  { term: "Deportación (Removal)", definition: "En inglés legal se llama 'removal': el proceso de expulsar de Estados Unidos a una persona que no es ciudadana. La orden de deportación normalmente la dicta un juez de inmigración tras una audiencia, aunque algunos procedimientos acelerados omiten al juez. Una orden de deportación puede impedir el regreso durante años o para siempre. No debe confundirse con el 'Poder de destitución' de funcionarios federales." },
  { term: "Derecho civil (Civil Law)", definition: "El área del derecho que trata disputas entre particulares (contratos, propiedad, lesiones), a diferencia del derecho penal. En casos civiles la sanción suele ser dinero, no cárcel." },
  { term: "Derecho común (Common Law)", definition: "Derecho desarrollado por decisiones judiciales a lo largo de siglos, no escrito por una legislatura. Muchos principios legales estadounidenses provienen de la tradición inglesa del common law." },
  { term: "Derecho penal (Criminal Law)", definition: "El área del derecho que trata delitos contra el estado (robo, agresión, homicidio). El gobierno siempre es el acusador. Las penas incluyen multas, libertad a prueba o prisión." },
  { term: "Derechos civiles (Civil Rights)", definition: "Derechos que protegen a las personas contra la discriminación. La cláusula de protección igualitaria de la 14.ª Enmienda es la base de la mayoría del derecho de derechos civiles." },
  { term: "Derechos de aduana (Duties)", definition: "Impuestos sobre bienes, especialmente importaciones; hoy suelen llamarse aranceles. La Constitución da al Congreso el poder de establecer y recaudar estos derechos. Compare con 'Arancel.'" },
  { term: "Derechos Miranda (Miranda Rights)", definition: "Su derecho a guardar silencio y a tener un abogado presente durante un interrogatorio policial. La policía debe informarle de estos derechos antes de interrogarle bajo custodia." },
  { term: "Derechos no enumerados (Unenumerated Rights)", definition: "Derechos no listados específicamente en la Constitución pero igualmente protegidos. La 9.ª Enmienda dice que sus derechos no se limitan a lo escrito." },
  { term: "Derogar (Repeal)", definition: "Revocar o cancelar oficialmente una ley. La 21.ª Enmienda derogó la 18.ª (la Prohibición). Es la única vez que se ha derogado una enmienda." },
  { term: "Descubrimiento de pruebas (Discovery)", definition: "El proceso previo al juicio donde cada parte puede obtener evidencia de la otra, incluidos documentos, registros y testimonios." },
  { term: "Despotismo (Despotism)", definition: "Poder absoluto y tiránico. La Declaración de Independencia dice que cuando un gobierno 'evidencia un designio de reducirlos bajo un despotismo absoluto', el pueblo tiene derecho a derrocarlo." },
  { term: "Detenido (Detained)", definition: "Retenido por el gobierno sin arresto ni cargos formales. Los detenidos migratorios, por ejemplo, pueden permanecer retenidos por períodos largos. La Constitución limita cuánto pueden retenerle sin cargos." },
  { term: "Devolver el caso (Remand)", definition: "Cuando un tribunal superior regresa un caso a uno inferior para más procedimientos. La Corte Suprema suele devolver casos con instrucciones sobre cómo aplicar su fallo." },
  { term: "Dicta", definition: "Comentarios en una opinión judicial que no son esenciales para la decisión. No obligan a tribunales futuros, pero pueden influir en cómo evoluciona el derecho." },
  { term: "Difamación escrita (Libel)", definition: "Una declaración escrita falsa que daña la reputación de alguien. Para que un funcionario público gane una demanda, debe probar 'malicia real': que el autor sabía que era falsa o actuó con desprecio temerario por la verdad." },
  { term: "Difamación oral (Slander)", definition: "Una declaración hablada falsa que daña la reputación. La contraparte oral del libelo (difamación escrita)." },
  { term: "Disolver (Dissolve)", definition: "Terminar o deshacer formalmente. La Declaración habla de disolver los 'lazos políticos', es decir, terminar la relación política entre las colonias y Gran Bretaña." },
  { term: "Doble juicio (Double Jeopardy)", definition: "Ser juzgado dos veces por el mismo delito. La 5.ª Enmienda lo prohíbe. Sin embargo, el estado y el gobierno federal son 'soberanos' distintos, así que ambos pueden procesarle." },
  { term: "Doble soberanía (Dual Sovereignty)", definition: "El principio de que los gobiernos estatal y federal son autoridades legales separadas. Por eso, ambos pueden procesarle por el mismo acto sin violar la prohibición del doble juicio." },
  { term: "Doctrina (Doctrine)", definition: "Un principio o conjunto de principios establecidos por decisiones judiciales. Ejemplos: la 'doctrina de incorporación' y la 'regla de exclusión.' Las doctrinas guían la interpretación del derecho." },
  { term: "Doctrina anticomandeo (Anti-Commandeering Doctrine)", definition: "El principio de que el gobierno federal no puede obligar a funcionarios estatales o locales a aplicar leyes federales. Los estados pueden cooperar, pero no ser forzados." },
  { term: "Doctrina de incorporación (Incorporation Doctrine)", definition: "El principio legal de que la mayor parte de la Carta de Derechos aplica a los gobiernos estatales a través de la 14.ª Enmienda, no solo al gobierno federal." },
  { term: "Doctrina de la plena vista (Plain View Doctrine)", definition: "Una regla que permite a la policía incautar evidencia sin orden judicial si está legalmente en un lugar y la naturaleza ilegal del objeto es evidente de inmediato. Por ejemplo, un agente que está legalmente dentro de una casa durante una emergencia puede incautar drogas que están sobre una mesa." },
  { term: "Doctrina de las cuestiones mayores (Major Questions Doctrine)", definition: "El principio de que las agencias federales no pueden tomar decisiones de gran trascendencia económica o política sin autorización clara del Congreso. La Corte Suprema adoptó formalmente el nombre en West Virginia v. EPA (2022), con base en casos anteriores. En Learning Resources v. Trump (2026), tres jueces de la mayoría también se apoyaron en ella al sostener que una ley de poderes de emergencia no permite al Presidente imponer aranceles." },
  { term: "Doctrina de no delegación (Nondelegation Doctrine)", definition: "El principio de que el Congreso no puede ceder su poder legislativo a agencias o al ejecutivo. Los tribunales permiten que el Congreso dé discreción a las agencias siempre que fije un 'principio inteligible' que las guíe, una prueba que la Corte reafirmó en FCC v. Consumers' Research (2025) al avalar el fondo que paga servicios de comunicaciones para zonas rurales, escuelas, bibliotecas y consumidores de bajos ingresos. Rara vez se aplica hoy, pero se invoca periódicamente como freno a las agencias regulatorias." },
  { term: "Dotado (Endowed)", definition: "Otorgado o concedido. La Declaración dice que las personas están 'dotadas por su Creador de ciertos derechos inalienables': esos derechos vienen con ser humano, no los da el gobierno." },

  // === E ===
  { term: "Ejército permanente (Standing Army)", definition: "Una fuerza militar permanente mantenida en tiempos de paz. Los Fundadores temían los ejércitos permanentes como herramientas de tiranía. La Constitución limita el financiamiento del ejército a dos años a la vez, así que el Congreso debe renovarlo continuamente." },
  { term: "Elector desleal (Faithless Elector)", definition: "Un miembro del Colegio Electoral que vota por alguien distinto del candidato que prometió apoyar. En Chiafalo v. Washington (2020), la Corte Suprema sostuvo que los estados pueden multarlos o reemplazarlos, y muchos estados tienen leyes que lo hacen." },
  { term: "Electores (Electors)", definition: "Personas elegidas para emitir los votos del Colegio Electoral. Cada estado tiene electores según su delegación congresional. Se espera que voten como decidieron los votantes de su estado, y la Corte Suprema sostuvo en Chiafalo v. Washington (2020) que los estados pueden exigirlo." },
  { term: "Emolumentos (Emoluments)", definition: "Pagos, ganancias o beneficios recibidos por un cargo. La Constitución prohíbe a los funcionarios federales aceptar emolumentos de gobiernos extranjeros sin consentimiento del Congreso." },
  { term: "En cumplimiento de (Pursuance)", definition: "De acuerdo con o en ejecución de. La Cláusula de Supremacía dice que las leyes hechas 'en cumplimiento' de la Constitución son ley suprema: solo las leyes federales constitucionales superan a las estatales." },
  { term: "Enmendar (Amend)", definition: "Cambiar formalmente. El proceso habitual requiere la aprobación de 2/3 de ambas cámaras del Congreso y la ratificación de 3/4 de los estados." },
  { term: "Enmienda (Amendment)", definition: "Un cambio o adición formal a la Constitución. Hay 27 enmiendas. Las primeras 10 se llaman la Carta de Derechos." },
  { term: "Entorno de la vivienda (Curtilage)", definition: "El área inmediata alrededor de una casa, como el porche o el patio o la entrada de autos junto a la vivienda, que la 4.ª Enmienda protege como parte del hogar. En Florida v. Jardines (2013), llevar un perro antidrogas al porche sin orden judicial fue un registro inconstitucional." },
  { term: "Enumeración (Enumeration)", definition: "Un listado o conteo formal. La Constitución usa la palabra de dos formas: contar la población para repartir escaños y listar ('enumerar') derechos específicos. La 9.ª Enmienda dice que sus derechos no se limitan a los enumerados." },
  { term: "Equidad (Equity)", definition: "Una rama del derecho enfocada en la justicia cuando los remedios legales ordinarios son insuficientes. Los tribunales de equidad pueden emitir mandatos u ordenar acciones específicas, no solo indemnizaciones." },
  { term: "Escrito legal (Brief)", definition: "Un argumento legal escrito presentado a un tribunal. Los abogados presentan escritos para explicar su posición y citar leyes y casos relevantes." },
  { term: "Escrutinio estricto (Strict Scrutiny)", definition: "El nivel más alto de revisión judicial, aplicado cuando el gobierno restringe un derecho fundamental o discrimina por una clasificación sospechosa (como la raza). El gobierno debe probar un interés imperioso y usar los medios menos restrictivos." },
  { term: "Estado de la Unión (State of the Union)", definition: "El informe del Presidente al Congreso sobre la situación del país, exigido 'periódicamente' por el Artículo II, Sección 3. Hoy suele ser un discurso anual ante una sesión conjunta del Congreso, aunque los primeros presidentes a menudo lo enviaban por escrito." },
  { term: "Estatus de Protección Temporal (Temporary Protected Status)", definition: "Una protección humanitaria de corto plazo, conocida como TPS por sus siglas en inglés, que el Congreso creó en 1990. Permite a personas de un país designado vivir y trabajar en Estados Unidos mientras las condiciones allí, como un conflicto armado o un desastre natural, hacen inseguro el regreso. El Secretario de Seguridad Nacional decide si designa, prorroga o termina el TPS de un país, y algunas designaciones han durado décadas. En Mullin v. Doe (2026), la Corte sostuvo que los tribunales no pueden revisar impugnaciones no constitucionales contra esas decisiones, de modo que el fin del TPS para Haití y Siria podía entrar en vigor mientras continúan los juicios." },
  { term: "Evidenciar (Evinces)", definition: "Mostrar o demostrar claramente. La Declaración dice que cuando 'una larga serie de abusos evidencia un designio de reducirlos al despotismo', es decir, cuando el patrón muestra claramente intención tiránica, el pueblo debe actuar." },
  { term: "Evidente por sí mismo (Self-Evident)", definition: "Obviamente cierto sin necesidad de prueba. La Declaración dice 'sostenemos que estas verdades son evidentes por sí mismas: que todos los hombres son creados iguales.' Principios tan fundamentales que no requieren argumento." },
  { term: "Ex Parte", definition: "Latín para 'de una sola parte.' Un procedimiento legal donde solo una parte está presente. También se usa en nombres de casos, como 'Ex parte Merryman', un caso presentado solo por Merryman." },
  { term: "Expectativa razonable de privacidad (Reasonable Expectation of Privacy)", definition: "La prueba legal de si aplica la 4.ª Enmienda. Si usted tiene una expectativa subjetiva de privacidad que la sociedad reconoce como razonable, el gobierno generalmente necesita una orden judicial para inmiscuirse. En Chatrie v. United States (2026), la Corte sostuvo que las personas tienen una expectativa razonable de privacidad sobre el historial de ubicaciones del celular que registran empresas como Google, incluso durante un período corto." },
  { term: "Expresión simbólica (Symbolic Speech)", definition: "Expresión no verbal que comunica un mensaje: quemar una bandera, llevar un brazalete, arrodillarse durante el himno. Protegida por la 1.ª Enmienda." },
  { term: "Expropiación (Eminent Domain)", definition: "El poder del gobierno de tomar propiedad privada para uso público. La 5.ª Enmienda exige que le paguen una 'compensación justa.'" },
  { term: "Extradición (Extradition)", definition: "El proceso de transferir a una persona acusada de un delito de un estado (o país) a otro para enfrentar cargos. La Constitución exige a los estados devolver a los fugitivos." },

  // === F ===
  { term: "Federalismo (Federalism)", definition: "La división del poder entre el gobierno federal y los estatales. Cada uno tiene su propia esfera de autoridad." },
  { term: "Fianza (Bail)", definition: "Dinero pagado para salir de la cárcel mientras espera el juicio. La 8.ª Enmienda dice que no puede fijarse excesivamente alta." },
  { term: "Forma republicana de gobierno (Republican Form of Government)", definition: "Un gobierno donde el poder lo tienen el pueblo y sus representantes electos, no un rey o dictador. La Cláusula de Garantía de la Constitución (Artículo IV, Sección 4) asegura a cada estado una forma republicana de gobierno." },
  { term: "Foro público (Public Forum)", definition: "Un espacio de propiedad pública donde existe el derecho constitucional a expresarse, como calles, aceras y parques. El gobierno puede imponer restricciones razonables de horario, lugar y manera, pero no prohibir la expresión." },

  // === G ===
  { term: "Gerrymandering", definition: "Dibujar los límites de los distritos electorales para dar ventaja injusta a un partido. El nombre viene del gobernador Elbridge Gerry, cuyo mapa de 1812 incluía un distrito con forma de salamandra. En Rucho v. Common Cause (2019), la Corte Suprema sostuvo que los tribunales federales no pueden decidir reclamos de gerrymandering partidista, aunque el gerrymandering racial todavía puede impugnarse. En Louisiana v. Callais (2026), la Corte anuló un mapa congresional de Luisiana por ser gerrymandering racial, porque la Ley de Derecho al Voto no exigía su segundo distrito de mayoría negra, y sostuvo que esa Ley solo alcanza a los mapas de distritos cuando las pruebas sugieren con fuerza una discriminación intencional." },
  { term: "Gran jurado (Grand Jury)", definition: "Un grupo de ciudadanos que decide si hay evidencia suficiente para acusar formalmente a alguien de un delito grave. Requerido por la 5.ª Enmienda en casos federales." },

  // === H ===
  { term: "Habeas Corpus", definition: "Latín para 'que presenten el cuerpo.' Su derecho a comparecer ante un juez y exigir que el gobierno pruebe que tiene autoridad legal para retenerle. La protección más fundamental contra el encarcelamiento ilegal. En A.A.R.P. v. Trump (2025), una resolución provisional, la Corte sostuvo que un aviso de unas 24 horas no bastaba para las personas que el gobierno buscaba expulsar bajo la Ley de Enemigos Extranjeros; deben tener tiempo para acudir primero a un tribunal." },

  // === I ===
  { term: "Impeler (Impel)", definition: "Empujar hacia la acción. La Declaración dice que los colonos deben 'declarar las causas que los impelen a la separación', es decir, explicar qué los empuja a romper." },
  { term: "Imponer (Levy)", definition: "Establecer o recaudar. El Congreso tiene el poder de 'imponer' (recaudar) impuestos y de 'hacer' (librar) la guerra." },
  { term: "Impuesto al voto (Poll Tax)", definition: "Una tarifa exigida para votar. Usada históricamente para impedir el voto de los pobres y de los ciudadanos negros. Prohibida en elecciones federales por la 24.ª Enmienda y en todas por la Corte Suprema." },
  { term: "Impuestos aduaneros (Imposts)", definition: "Impuestos o aranceles sobre bienes importados. La Constitución da al Congreso el poder de recaudarlos como fuente de ingresos." },
  { term: "Inalienable", definition: "Que no puede quitarse ni cederse. También se escribe 'unalienable' en el texto original. La Declaración dice que sus derechos a la vida, la libertad y la búsqueda de la felicidad son inalienables: ningún gobierno puede eliminarlos." },
  { term: "Incautación (Seizure)", definition: "Cuando el gobierno toma posesión de una persona o propiedad. La 4.ª Enmienda protege contra 'incautaciones irrazonables.' Ser detenido por la policía es una incautación de su persona." },
  { term: "Inconstitucional (Unconstitutional)", definition: "En violación de la Constitución. Las leyes, órdenes ejecutivas o acciones del gobierno que contradicen la Constitución pueden ser declaradas inconstitucionales y anuladas por los tribunales." },
  { term: "Indulto (Pardon)", definition: "El poder del Presidente de perdonar un delito federal, eliminando el castigo. Los indultos no pueden deshacer un juicio político. Los gobernadores pueden indultar delitos estatales." },
  { term: "Infringido (Infringed)", definition: "Violado o debilitado. La 2.ª Enmienda dice que el derecho a portar armas 'no será infringido': no puede ser violado ni socavado." },
  { term: "Inmunidad (Immunity)", definition: "Protección legal contra demandas o procesos. Tipos: inmunidad soberana (el gobierno no puede ser demandado), inmunidad calificada (protege a funcionarios) e inmunidad diplomática." },
  { term: "Inmunidad calificada (Qualified Immunity)", definition: "Un escudo legal que protege a los funcionarios de responsabilidad personal salvo que hayan violado derechos 'claramente establecidos.' Normalmente eso significa que un caso anterior con hechos similares debe haber dejado claro que la conducta específica era ilegal; en Zorn v. Linton (2026), la Corte concedió inmunidad a un oficial que usó una llave de muñeca rutinaria para levantar a una manifestante en una sentada después de advertirle. Sus defensores dicen que protege a funcionarios que deben decidir en segundos. Los críticos dicen que hace casi imposible exigir cuentas a policías y funcionarios." },
  { term: "Inmunidad soberana (Sovereign Immunity)", definition: "El principio de que el gobierno no puede ser demandado sin su consentimiento. La 11.ª Enmienda limita las demandas contra estados en tribunales federales. Una entidad creada por un estado comparte esa inmunidad solo si es realmente un brazo del estado; una corporación jurídicamente independiente que paga sus propias sentencias, por lo general, no la comparte (Galette v. New Jersey Transit Corp. (2026))." },
  { term: "Insurrección (Insurrection)", definition: "Un levantamiento violento contra el gobierno. El Congreso puede convocar a la milicia para sofocar insurrecciones (Artículo I, Sección 8), y la Sección 3 de la 14.ª Enmienda prohíbe ocupar cargos federales o estatales a quien, tras jurar como funcionario apoyar la Constitución, participó en una insurrección. El Congreso puede levantar esa prohibición con el voto de dos tercios de cada cámara." },
  { term: "Intención original (Original Intent)", definition: "Un método de interpretación constitucional basado en lo que sus autores quisieron decir al escribirla. Contrasta con los enfoques de 'Constitución viva' que permiten que el significado evolucione." },
  { term: "Interés imperioso (Compelling Interest)", definition: "Un propósito gubernamental tan importante que puede justificar restringir un derecho fundamental. Para superar el 'escrutinio estricto', el gobierno debe mostrar un interés imperioso y usar los medios menos restrictivos posibles." },
  { term: "Interpretar (Construe)", definition: "Determinar el significado de una ley o texto legal. La 9.ª Enmienda dice que listar ciertos derechos no debe 'interpretarse' como negación de otros derechos que usted conserva." },
  { term: "Interrogatorio bajo custodia (Custodial Interrogation)", definition: "Interrogatorio policial de una persona bajo custodia (arrestada o sin libertad para irse). Los avisos Miranda deben darse antes de que comience." },

  // === J ===
  { term: "Juicio político (Impeachment)", definition: "El proceso de acusar formalmente a un funcionario federal de mala conducta. La Cámara acusa, el Senado juzga (condena o absuelve). Se requieren 2/3 de los senadores presentes para condenar y destituir." },
  { term: "Juramento del cargo (Oath of Office)", definition: "Una promesa solemne de defender la Constitución, exigida a todos los funcionarios. El juramento del Presidente está en la Constitución. No puede exigirse ninguna prueba religiosa." },
  { term: "Jurisdicción (Jurisdiction)", definition: "La autoridad de un tribunal para atender y decidir un caso. Los tribunales federales tienen jurisdicción sobre la ley federal, cuestiones constitucionales y disputas entre estados." },
  { term: "Jurisdicción de apelación (Appellate Jurisdiction)", definition: "El poder de un tribunal superior de revisar decisiones de tribunales inferiores. La Corte Suprema opera mayormente así." },
  { term: "Jurisdicción original (Original Jurisdiction)", definition: "Los casos que un tribunal atiende primero, antes de cualquier apelación. La Corte Suprema tiene jurisdicción original en casos que involucran estados o embajadores." },
  { term: "Jurisprudencia (Case Law)", definition: "Derecho creado por decisiones judiciales en lugar de legislación. Cuando los jueces interpretan la Constitución o las leyes, sus fallos se vuelven jurisprudencia que guía decisiones futuras." },

  // === L ===
  { term: "Lealtad (Allegiance)", definition: "Fidelidad debida a un gobierno o gobernante. La Declaración de Independencia declaró a las colonias 'absueltas de toda lealtad a la Corona británica.'" },
  { term: "Lectura de cargos (Arraignment)", definition: "Una audiencia donde a la persona acusada de un delito se le informa formalmente de qué se le acusa y se le pide declararse culpable o no culpable." },
  { term: "Legitimación procesal (Standing)", definition: "El derecho legal a demandar. Debe mostrar que sufrió un daño concreto causado por el demandado que un tribunal puede remediar. Sin legitimación, el caso se desestima." },
  { term: "Ley (Statute)", definition: "Una ley aprobada por una legislatura (el Congreso o una estatal). Distinta de la jurisprudencia, que viene de los tribunales, y de las regulaciones, que vienen de las agencias." },
  { term: "Ley de identificación obligatoria (Stop-and-Identify Law)", definition: "Una ley estatal que obliga a una persona a dar su nombre a la policía durante una detención legal basada en sospecha razonable. La Corte Suprema validó estas leyes en Hiibel v. Sixth Judicial District Court (2004), pero solo algunos estados las tienen y los detalles varían. Incluso donde aplican, en general no tiene que responder otras preguntas." },
  { term: "Ley de proscripción (Bill of Attainder)", definition: "Una ley que castiga a una persona o grupo específico sin juicio. La Constitución las prohíbe explícitamente." },
  { term: "Ley ex post facto (Ex Post Facto Law)", definition: "Una ley que castiga una conducta que era legal cuando ocurrió, o que aumenta la pena de un delito después de cometido. La Constitución las prohíbe en materia penal. En Ellingburg v. United States (2026), la Corte sostuvo que la restitución ordenada según una ley federal de protección a las víctimas es un castigo penal para estos efectos." },
  { term: "Libertad a prueba (Probation)", definition: "Una sentencia que permite a una persona condenada permanecer en la comunidad bajo supervisión en lugar de ir a la cárcel, o después de un breve período en ella. Incumplir las condiciones, como faltar a las citas de control o cometer un nuevo delito, puede llevar a la cárcel. Las personas en libertad a prueba suelen tener menos derechos de privacidad, incluida la posibilidad de ser registradas." },
  { term: "Libertad condicional (Parole)", definition: "La liberación anticipada y supervisada de la prisión antes de cumplir toda la sentencia. Quien está en libertad condicional debe cumplir condiciones y puede volver a prisión si las viola; el sistema federal eliminó esta figura para los delitos cometidos desde noviembre de 1987. En la ley de inmigración, 'parole' significa algo distinto: un permiso para entrar o permanecer temporalmente en Estados Unidos." },
  { term: "Libertades civiles (Civil Liberties)", definition: "Libertades individuales que el gobierno no puede quitar, como la libertad de expresión, la religión y el derecho a un juicio justo." },
  { term: "Libre de irse (Free to Leave)", definition: "La prueba para saber si un encuentro con la policía es voluntario o una detención. Si una persona razonable se sentiría libre de irse o de terminar la conversación, el encuentro es voluntario; si no, la persona ha sido detenida y aplica la 4.ª Enmienda. Preguntar '¿Soy libre de irme?' ayuda a aclarar la situación." },

  // === M ===
  { term: "Magistrado (Magistrate)", definition: "Un funcionario judicial con autoridad limitada que suele manejar audiencias preliminares, fianzas y emisión de órdenes judiciales. No es juez pleno pero ejerce funciones judiciales importantes." },
  { term: "Magnanimidad (Magnanimity)", definition: "Generosidad y nobleza de espíritu. La Declaración dice que los colonos 'apelaron a su justicia y magnanimidad innatas', con la esperanza de que el pueblo británico los tratara con justicia." },
  { term: "Malicia real (Actual Malice)", definition: "El estándar legal para la difamación de funcionarios públicos y figuras públicas. Para ganar una demanda, deben probar que la declaración se hizo sabiendo que era falsa o con desprecio temerario por la verdad. Establecido en New York Times v. Sullivan." },
  { term: "Mandamus", definition: "Latín para 'ordenamos.' Una orden judicial que manda a un funcionario cumplir un deber legal. El caso Marbury v. Madison giró en torno a una petición de mandamus." },
  { term: "Mandato judicial (Injunction)", definition: "Una orden judicial que exige hacer o dejar de hacer algo. Los tribunales pueden emitirlos para bloquear la aplicación de leyes inconstitucionales. Compare con 'Medida cautelar universal.'" },
  { term: "Medida cautelar universal (Universal Injunction)", definition: "Una orden judicial que impide al gobierno aplicar una ley o política a cualquier persona, no solo a quienes demandaron; también se llama medida cautelar nacional. En Trump v. CASA (2025), una resolución provisional, la Corte Suprema sostuvo que las medidas cautelares universales probablemente exceden el poder que el Congreso ha otorgado a los tribunales federales, así que la protección no debe ir más allá de lo necesario para proteger por completo a cada demandante con legitimación procesal. Los grupos grandes todavía pueden pedir protección en conjunto mediante una demanda colectiva. Compare con 'Mandato judicial.'" },
  { term: "Menospreciar (Disparage)", definition: "Restar importancia o tratar como insignificante. La 9.ª Enmienda dice que listar ciertos derechos no debe 'negar ni menospreciar' otros: los derechos no listados también cuentan." },
  { term: "Mercenarios (Mercenaries)", definition: "Soldados contratados que luchan por dinero y no por su propio país. La Declaración acusa al Rey de 'transportar grandes ejércitos de mercenarios extranjeros', en referencia a las tropas alemanas, a menudo llamadas hessianos, contratadas para combatir a los colonos." },
  { term: "Milicia (Militia)", definition: "Una fuerza militar compuesta por ciudadanos comunes, no soldados profesionales. La 2.ª Enmienda menciona una 'milicia bien regulada.' Hoy la Guardia Nacional es la milicia organizada de cada estado, y la ley federal define la 'milicia no organizada' como la mayoría de los hombres aptos de 17 a 44 años que son ciudadanos o han declarado su intención de serlo." },
  { term: "Moneda de curso legal (Tender)", definition: "Una forma de pago. La Constitución dice que los estados solo pueden hacer del oro y la plata 'moneda de curso legal', es decir, aceptable para pagar deudas." },
  { term: "Multas excesivas (Excessive Fines)", definition: "Sanciones económicas desproporcionadas a la falta. La 8.ª Enmienda las prohíbe, y se ha aplicado para limitar el decomiso civil de bienes." },

  // === N ===
  { term: "Naturalización (Naturalization)", definition: "El proceso legal de convertirse en ciudadano si no nació siéndolo. La 14.ª Enmienda también otorga la ciudadanía a todas las personas nacidas en Estados Unidos y sujetas a su jurisdicción." },
  { term: "Neutralidad de contenido (Content Neutrality)", definition: "El principio de que el gobierno no puede favorecer ni castigar la expresión según su mensaje. Una ley que prohíbe todos los letreros es neutral; una que prohíbe solo los políticos no lo es." },
  { term: "No obstante (Notwithstanding)", definition: "A pesar de. Cuando la Constitución dice que la ley federal es suprema 'no obstante cualquier disposición en contrario de la Constitución o leyes de cualquier estado', la ley estatal pierde aunque diga lo contrario." },
  { term: "Nombramiento en receso (Recess Appointment)", definition: "Cuando el Presidente llena un puesto mientras el Senado no sesiona, esquivando la confirmación normal. El nombramiento es temporal." },
  { term: "Notificación de comparecencia (Notice to Appear)", definition: "El documento de cargos (Formulario I-862) que inicia un proceso de deportación en el tribunal de inmigración. Indica las razones del gobierno para pedir la deportación y debe señalar la fecha, la hora y el lugar de la primera audiencia. No presentarse a una audiencia puede resultar en una orden de deportación en su ausencia." },
  { term: "Nulo (Void)", definition: "Sin fuerza legal. Una ley inconstitucional es nula y se trata como si nunca hubiera existido." },

  // === O ===
  { term: "Opinión de pluralidad (Plurality)", definition: "Una opinión judicial con más votos que ninguna otra pero sin mayoría. Sienta precedente más débil que una opinión mayoritaria, pero guía casos futuros." },
  { term: "Opinión mayoritaria (Majority Opinion)", definition: "La decisión oficial del tribunal, apoyada por más de la mitad de los jueces. Sienta precedente vinculante para los tribunales inferiores." },
  { term: "Orden administrativa (Administrative Warrant)", definition: "Una orden emitida y firmada por un oficial de inmigración, no por un juez, como los formularios I-200 (arresto) o I-205 (deportación) de ICE. Puede respaldar un arresto, pero no autoriza a los agentes a entrar en una vivienda sin el consentimiento de quienes están adentro. Compare con 'Orden judicial firmada por un juez.'" },
  { term: "Orden de geovalla (Geofence Warrant)", definition: "Una orden judicial que obliga a una empresa, como Google, a entregar los datos de ubicación de todos los teléfonos que estuvieron dentro de una zona determinada durante un tiempo determinado, a menudo para encontrar sospechosos de un delito. En Chatrie v. United States (2026), la Corte Suprema sostuvo que obtener de una empresa así el historial de ubicaciones del celular de una persona es un registro según la 4.ª Enmienda, pero dejó abierta la cuestión de si las órdenes de geovalla, que abarcan datos de todas las personas en una zona, pueden cumplir con la 4.ª Enmienda." },
  { term: "Orden ejecutiva (Executive Order)", definition: "Una directiva del Presidente a las agencias federales. Puede tener fuerza de ley cuando se basa en la autoridad constitucional o legal del Presidente, pero no puede contradecir la Constitución ni una ley del Congreso. Por ejemplo, en Trump v. Barbara (2026), la Corte falló en contra de una orden ejecutiva que habría negado la ciudadanía a algunos niños nacidos en EE. UU. Polémica cuando se usa para políticas mayores." },
  { term: "Orden judicial (Warrant)", definition: "Una orden de un tribunal, firmada por un juez o magistrado, que autoriza a la policía a registrar un lugar específico o arrestar a una persona específica. La 4.ª Enmienda exige que se base en causa probable y describa los detalles. Compare con 'Orden administrativa.'" },
  { term: "Orden judicial firmada por un juez (Judicial Warrant)", definition: "Una orden firmada por un juez o magistrado tras determinar que hay causa probable, como exige la 4.ª Enmienda. Indica el tribunal y la persona o el lugar específico, y es lo que la policía generalmente necesita para entrar en una vivienda sin consentimiento (Payton v. New York (1980))." },
  { term: "Ordenar judicialmente (Enjoin)", definition: "Mandar mediante orden judicial (mandato) que alguien haga o deje de hacer algo. Un tribunal puede ordenar al gobierno no aplicar una ley inconstitucional." },
  { term: "Ordenar y establecer (Ordain and Establish)", definition: "Crear y poner en vigor oficialmente. 'Nosotros el Pueblo... ordenamos y establecemos esta Constitución' significa que el pueblo crea y autoriza este sistema de gobierno." },

  // === P ===
  { term: "Parada por pretexto (Pretextual Stop)", definition: "Una parada en la que la policía usa una infracción menor, como una luz trasera rota, como motivo legal para detener a alguien a quien quiere investigar por otra cosa. Según Whren v. United States (1996), estas paradas son válidas bajo la 4.ª Enmienda si el agente tenía causa probable de la infracción menor, aunque una parada basada en la raza puede impugnarse bajo la Cláusula de Protección Igualitaria." },
  { term: "Parada Terry (Terry Stop)", definition: "Una detención policial breve basada en sospecha razonable de que una persona está involucrada en un delito, llamada así por Terry v. Ohio (1968). Debe ser corta y limitarse a confirmar o descartar esa sospecha." },
  { term: "Pasajero (Transient)", definition: "Temporal o fugaz. La Declaración dice que los gobiernos 'no deben cambiarse por causas ligeras y pasajeras': no hay que rebelarse por problemas fugaces." },
  { term: "Patentes de corso (Letters of Marque and Reprisal)", definition: "Licencias gubernamentales que autorizaban a ciudadanos privados a atacar barcos enemigos en guerra. La Constitución permite al Congreso emitirlas y lo prohíbe a los estados. Ya no se usan." },
  { term: "Pato cojo (Lame Duck)", definition: "Un funcionario electo que termina su mandato tras perder una elección o no buscar la reelección. La 20.ª Enmienda acortó este período moviendo la investidura de marzo a enero." },
  { term: "Penumbra", definition: "Una zona implícita de protección. El juez Douglas argumentó que las garantías específicas de la Carta de Derechos tienen 'penumbras', protecciones implícitas más allá de su texto literal, que crean el derecho a la privacidad." },
  { term: "Peonaje (Peonage)", definition: "Un sistema de trabajo forzado para pagar una deuda. Esencialmente esclavitud por deudas. Prohibido por la 13.ª Enmienda y las leyes federales contra el peonaje." },
  { term: "Persecución inmediata (Hot Pursuit)", definition: "Una excepción al requisito de orden judicial que puede permitir a la policía seguir a un sospechoso que huye hasta dentro de una vivienda sin orden. En Lange v. California (2021), la Corte Suprema sostuvo que perseguir a alguien sospechoso de un delito menor no justifica automáticamente entrar en una casa; los agentes deben demostrar una emergencia real." },
  { term: "Pesos y contrapesos (Checks and Balances)", definition: "El sistema donde cada rama del gobierno puede limitar a las otras. El Congreso hace leyes, el Presidente puede vetarlas y los tribunales pueden anularlas por inconstitucionales." },
  { term: "Petición (Petition)", definition: "Una solicitud formal al gobierno. La 1.ª Enmienda protege su derecho a 'presentar peticiones al gobierno para la reparación de agravios': exigir formalmente que se resuelvan los problemas." },
  { term: "Plazo de ratificación (Ratification Deadline)", definition: "Un límite de tiempo que fija el Congreso para que los estados ratifiquen una enmienda propuesta, a menudo de siete años. La Constitución no lo exige, pero en Dillon v. Gloss (1921) la Corte sostuvo que el Congreso puede fijar un plazo razonable. La 27.ª Enmienda no tenía plazo y fue ratificada en 1992, más de 200 años después de ser propuesta." },
  { term: "Plena fe y crédito (Full Faith and Credit)", definition: "El requisito constitucional de que cada estado honre las leyes, registros y decisiones judiciales de los demás. Por ejemplo, una sentencia ganada en un estado puede hacerse cumplir en otro." },
  { term: "Poder de destitución (Removal Power)", definition: "El poder del Presidente de despedir a funcionarios del poder ejecutivo. La Constitución no lo menciona directamente, pero la Corte lo vincula con el poder ejecutivo que el Artículo II otorga al Presidente. En Trump v. Slaughter (2026), la Corte sostuvo que los funcionarios que ejercen poder ejecutivo, incluidos los miembros de la Comisión Federal de Comercio (FTC), deben poder ser destituidos por el Presidente a voluntad, y afirmó que de Humphrey's Executor v. United States (1935), que había avalado límites a la destitución de los comisionados de la FTC, no queda nada más que su observación de que una agencia que no ejerce poder ejecutivo no necesita estar sujeta a destitución a voluntad. En Trump v. Cook (2026), una resolución provisional, la Corte afirmó que la protección contra la destitución de los gobernadores de la Reserva Federal es compatible con la Constitución y mantuvo en su cargo a la gobernadora Lisa Cook mientras continúa su caso. No debe confundirse con 'Deportación (Removal).'" },
  { term: "Poder de policía (Police Power)", definition: "La amplia autoridad de los estados para legislar sobre salud, seguridad, bienestar y moral públicos. Es la fuente de la mayoría de las regulaciones estatales, desde límites de velocidad hasta códigos de construcción." },
  { term: "Poderes concurrentes (Concurrent Powers)", definition: "Poderes compartidos por los gobiernos federal y estatales, como gravar impuestos, construir carreteras y crear tribunales." },
  { term: "Poderes enumerados (Enumerated Powers)", definition: "Poderes específicamente listados en la Constitución como propios del Congreso (Artículo I, Sección 8). Si no está listado, la 10.ª Enmienda dice que pertenece a los estados o al pueblo." },
  { term: "Poderes reservados (Reserved Powers)", definition: "Poderes que la Constitución no otorga al gobierno federal ni prohíbe a los estados. Según la 10.ª Enmienda, pertenecen a los estados o al pueblo." },
  { term: "Posteridad (Posterity)", definition: "Las generaciones futuras. El Preámbulo dice que la Constitución se establece para 'asegurar los beneficios de la libertad para nosotros y nuestra posteridad': para nosotros y todos los estadounidenses futuros." },
  { term: "Precedente (Precedent)", definition: "Una decisión judicial previa que guía casos futuros con hechos similares. Los tribunales inferiores están obligados por los precedentes de los superiores." },
  { term: "Preeminencia federal (Preemption)", definition: "Cuando la ley federal desplaza a la estatal sobre el mismo tema. Se basa en la Cláusula de Supremacía. Si el Congreso ocupa un campo regulatorio, los estados no pueden legislar en contra." },
  { term: "Presentación del gran jurado (Presentment)", definition: "Una acusación formal de delito emitida por un gran jurado por iniciativa propia (no a petición del fiscal). La 5.ª Enmienda las menciona junto a las acusaciones formales." },
  { term: "Privar del voto (Disenfranchise)", definition: "Quitar a alguien el derecho al voto. Históricamente, los estadounidenses negros fueron privados del voto con impuestos, pruebas de alfabetización y otras barreras. La pérdida del voto por condenas aún afecta a millones." },
  { term: "Privilegio ejecutivo (Executive Privilege)", definition: "El derecho reclamado por el Presidente de mantener confidenciales ciertas comunicaciones. No aparece en la Constitución pero los tribunales lo reconocen de forma limitada." },
  { term: "Privilegios e inmunidades (Privileges and Immunities)", definition: "Derechos y protecciones de la ciudadanía. La 14.ª Enmienda dice que los estados no pueden restringirlos. El Artículo IV exige extenderlos a ciudadanos de otros estados." },
  { term: "Procedimiento de emergencia (Emergency Docket)", definition: "La forma en que la Corte Suprema resuelve solicitudes urgentes, como los pedidos de suspender la orden de un tribunal inferior mientras continúa una apelación. Suelen decidirse con rapidez, sin alegatos orales y a veces sin una explicación escrita, por lo que algunos lo llaman 'shadow docket' (expediente en la sombra). Sus resoluciones son provisionales, no decisiones definitivas sobre el fondo, pero pueden tener efectos importantes, como en Trump v. CASA (2025) y A.A.R.P. v. Trump (2025). En algunas solicitudes, la Corte escucha alegatos orales primero, como hizo en Trump v. Cook (2026)." },
  { term: "Procesar (Prosecute)", definition: "Presentar cargos penales contra alguien y buscar su condena en el tribunal. El gobierno es el acusador en los casos penales." },
  { term: "Protección igualitaria (Equal Protection)", definition: "El requisito de la 14.ª Enmienda de que los estados traten a todas las personas por igual ante la ley. Al gobierno federal se le aplica el mismo estándar a través de la Cláusula del Debido Proceso de la 5.ª Enmienda. La base de la lucha contra la discriminación." },
  { term: "Prudencia (Prudence)", definition: "Buen juicio cuidadoso. La Declaración dice que 'la prudencia dictará que los gobiernos establecidos no se cambien por causas ligeras y pasajeras': no derrocar al gobierno por problemas menores." },
  { term: "Prueba de equilibrio (Balancing Test)", definition: "Un método que usan los tribunales para sopesar intereses en conflicto. Por ejemplo, la libertad de expresión de un empleado público contra la eficiencia operativa del empleador." },

  // === Q ===
  { term: "Quórum (Quorum)", definition: "El número mínimo de miembros presentes para que un cuerpo legislativo funcione. En el Congreso, la mayoría de cada cámara." },

  // === R ===
  { term: "Ratificación (Ratification)", definition: "Aprobación formal. La Constitución requirió la ratificación de 9 de 13 estados. Las enmiendas requieren la de 3/4 de los estados (38 de 50)." },
  { term: "Rectitud (Rectitude)", definition: "Integridad moral. Los firmantes apelaron 'al Juez Supremo del mundo por la rectitud de nuestras intenciones', pidiendo ser juzgados por la honestidad y la justicia de su propósito." },
  { term: "Recusación sin causa (Peremptory Challenge)", definition: "El derecho de rechazar a un posible jurado sin dar razón durante la selección. Cada parte tiene un número limitado. No puede usarse para excluir jurados por raza o género." },
  { term: "Recusarse (Recuse)", definition: "Cuando un juez se aparta voluntariamente de un caso por conflicto de interés o apariencia de parcialidad." },
  { term: "Registro administrativo (Administrative Search)", definition: "Una inspección gubernamental de una propiedad con fines regulatorios, como el cumplimiento del código de vivienda. Incluso las inspecciones rutinarias requieren consentimiento o una orden judicial, aunque con un estándar menor que el penal." },
  { term: "Registro con consentimiento (Consent Search)", definition: "Un registro que ocurre porque la persona lo aceptó. No se necesita orden judicial ni causa probable si el consentimiento es voluntario, y usted tiene derecho a decir que no. La policía no está obligada a decirle que puede negarse." },
  { term: "Registro tras arresto (Search Incident to Arrest)", definition: "Un registro sin orden judicial de la persona y el área a su alcance inmediato durante un arresto legal. La policía puede buscar armas y evidencia que podría destruirse, pero no registrar toda su casa, y necesita una orden judicial para revisar los datos de su teléfono (Riley v. California (2014))." },
  { term: "Regla de exclusión (Exclusionary Rule)", definition: "La evidencia obtenida mediante registros inconstitucionales (que violan la 4.ª Enmienda) generalmente no puede usarse en su contra en un juicio." },
  { term: "Regla de tocar y anunciarse (Knock and Announce)", definition: "La regla de que la policía que ejecuta una orden en una vivienda normalmente debe tocar, identificarse y dar a los ocupantes la oportunidad de abrir antes de entrar por la fuerza. Hay excepciones cuando anunciarse sería peligroso o permitiría destruir evidencia, y una violación por lo general no hace que se excluya la evidencia." },
  { term: "Remoción estipulada (Stipulated Removal)", definition: "Un acuerdo en el que una persona no ciudadana acepta una orden de deportación sin audiencia ante un juez de inmigración. Firmarlo implica renunciar a la oportunidad de defender su caso o pedir alivio migratorio, así que nunca lo firme sin hablar con un abogado." },
  { term: "Remoción expedita (Expedited Removal)", definition: "Un proceso acelerado que permite a los oficiales de inmigración ordenar la deportación de ciertas personas no ciudadanas sin audiencia ante un juez. Aplica a quienes llegan a la frontera sin documentos válidos y, según la política vigente, a quienes se encuentren en cualquier parte del país y no puedan probar dos años de presencia continua. Por ley, una persona que exprese temor de persecución o la intención de pedir asilo debe ser remitida a una entrevista de evaluación." },
  { term: "Renunciar a un derecho (Waive)", definition: "Ceder voluntariamente un derecho. Puede renunciar a su derecho a un jurado, a guardar silencio y a otros, pero la renuncia debe ser consciente, inteligente y voluntaria." },
  { term: "Reparación (Redress)", definition: "Un remedio o corrección de un mal. La 1.ª Enmienda protege su derecho a pedir al gobierno la 'reparación de agravios': exigir que los males se corrijan." },
  { term: "Reparto de escaños (Apportionment)", definition: "Dividir algo proporcionalmente. Los escaños de la Cámara se reparten entre los estados según los conteos de población del censo." },
  { term: "Residente permanente legal (Lawful Permanent Resident)", definition: "Una persona no ciudadana con derecho a vivir y trabajar en Estados Unidos de forma permanente, conocida por su tarjeta verde (green card). Normalmente puede solicitar la ciudadanía tras cinco años (tres si está casada con un ciudadano estadounidense), pero aún puede ser deportada por ciertos delitos o violaciones migratorias. Un residente permanente que regresa de un viaje al extranjero normalmente se considera ya admitido, pero si cometió ciertos delitos antes del viaje puede ser tratado como solicitante de admisión, incluso antes de cualquier condena (Blanche v. Lau (2026))." },
  { term: "Restringir (Abridging)", definition: "Reducir o limitar. Cuando la 1.ª Enmienda dice que el Congreso no puede aprobar leyes que 'restrinjan' la libertad de expresión, significa que no pueden limitar ni reducir sus derechos de expresión." },
  { term: "Retenidos (Retained)", definition: "Conservados. La 9.ª Enmienda dice que los derechos 'retenidos por el pueblo' están protegidos: usted conserva todos sus derechos naturales, no solo los listados." },
  { term: "Revisión judicial (Judicial Review)", definition: "El poder de los tribunales de declarar leyes inconstitucionales. No está explícito en la Constitución; la Corte Suprema lo estableció en Marbury v. Madison (1803)." },
  { term: "Revocar (Reverse)", definition: "Cuando un tribunal superior anula la decisión de uno inferior. Lo contrario de 'confirmar.'" },
  { term: "Revocar un precedente (Overrule)", definition: "Cuando un tribunal superior cambia o rechaza un principio legal de un caso anterior. Cuando la Corte Suprema revoca un precedente, la regla antigua deja de aplicar." },
  { term: "Riesgo penal (Jeopardy)", definition: "El riesgo de ser condenado y castigado por un delito. El 'doble riesgo' (double jeopardy) es ser puesto en riesgo dos veces por la misma ofensa, lo que la 5.ª Enmienda prohíbe." },

  // === S ===
  { term: "Salida voluntaria (Voluntary Departure)", definition: "Permiso para salir de Estados Unidos por cuenta propia, a su propio costo y antes de una fecha límite, en lugar de ser deportado formalmente. Evita algunas consecuencias de una orden de deportación, pero no cumplir el plazo trae multas y le impide recibir muchos beneficios migratorios en el futuro. Busque asesoría legal antes de aceptarla." },
  { term: "Sanción real (Assent)", definition: "Aprobación o consentimiento. La Declaración enumera la negativa del Rey a dar 'sanción a las leyes': bloqueaba leyes que los colonos necesitaban." },
  { term: "Sección 1983 (Section 1983)", definition: "Una ley federal (42 U.S.C. Sección 1983) que permite demandar a funcionarios estatales y locales por violar derechos constitucionales. La herramienta principal de las demandas de derechos civiles contra la policía y el gobierno. No cubre a los agentes federales; las demandas contra ellos dependen de la demanda Bivens, mucho más limitada." },
  { term: "Sede del juicio (Venue)", definition: "El lugar geográfico donde se celebra un juicio. La 6.ª Enmienda garantiza el juicio en el distrito donde ocurrió el delito." },
  { term: "Sedición (Sedition)", definition: "Expresión o conducta que alienta la rebelión contra el gobierno. La línea entre la disidencia política protegida y la sedición ilegal se ha debatido a lo largo de la historia estadounidense." },
  { term: "Sentencia declarativa (Declaratory Judgment)", definition: "Un fallo que declara los derechos de las partes sin ordenar ninguna acción específica. Se usa para aclarar derechos legales antes de que una disputa escale." },
  { term: "Separación de poderes (Separation of Powers)", definition: "Dividir el gobierno en tres ramas: legislativa (hace leyes), ejecutiva (las aplica) y judicial (las interpreta). Evita que una rama se vuelva demasiado poderosa." },
  { term: "Servidumbre involuntaria (Involuntary Servitude)", definition: "Ser forzado a trabajar contra su voluntad. Prohibida por la 13.ª Enmienda salvo como castigo por un delito. Aplica a situaciones como la trata de personas y el trabajo forzado." },
  { term: "Sesión pro forma (Pro Forma Session)", definition: "Una sesión breve del Congreso, a veces de segundos, celebrada para técnicamente seguir 'en sesión.' Se usa para impedir nombramientos presidenciales en receso." },
  { term: "Sin objeto (Moot)", definition: "Que ya no es una controversia viva. Un caso se vuelve 'sin objeto' cuando la disputa se resolvió o el asunto ya no importa, y los tribunales generalmente no fallan sobre casos así." },
  { term: "Soberanía popular (Popular Sovereignty)", definition: "El principio de que el poder del gobierno proviene del pueblo. 'Nosotros el Pueblo' lo establece en las primeras tres palabras de la Constitución." },
  { term: "Solicitud de retención (Detainer)", definition: "Una solicitud (Formulario I-247A de ICE) que pide a una cárcel local retener a una persona hasta 48 horas después del momento en que debía ser liberada, para que los agentes de inmigración la pongan bajo su custodia. No la firma un juez, y varios tribunales han sostenido que encarcelar a alguien solo con base en esta solicitud puede violar la 4.ª Enmienda." },
  { term: "Sospecha razonable (Reasonable Suspicion)", definition: "Un estándar menor que la causa probable, basado en hechos concretos y no en una corazonada. La policía necesita sospecha razonable para detenerle e interrogarle brevemente (una 'parada Terry') y para cachearle si cree que está armado, pero necesita causa probable para arrestarle o hacer un registro completo. Los tribunales evalúan todos los hechos en conjunto y no uno por uno, y la sospecha razonable no tiene que descartar una explicación inocente (District of Columbia v. R.W. (2026))." },
  { term: "Stare Decisis", definition: "Latín para 'atenerse a lo decidido.' El principio de que los tribunales deben seguir el precedente y no revocar fallos establecidos sin razones de peso. Da estabilidad y previsibilidad al derecho." },
  { term: "Sucesión presidencial (Presidential Succession)", definition: "El orden en que los funcionarios asumen el cargo si el Presidente muere, renuncia o es destituido. El Vicepresidente es el primero según la 25.ª Enmienda; después, la Ley de Sucesión Presidencial de 1947 fija el orden, comenzando por el Presidente de la Cámara de Representantes y el Presidente pro tempore del Senado, seguidos por los miembros del Gabinete." },
  { term: "Sufragio (Suffrage)", definition: "El derecho al voto. Las enmiendas 15.ª, 19.ª, 24.ª y 26.ª expandieron el sufragio a distintos grupos." },
  { term: "Suprimir evidencia (Suppress)", definition: "Excluir evidencia de un juicio. Si la policía la obtuvo mediante un registro inconstitucional, un juez puede 'suprimirla': el jurado nunca la ve." },
  { term: "Suspensión de pena (Reprieve)", definition: "Una postergación temporal de una sentencia, especialmente una de muerte. El Presidente puede concederlas para delitos federales." },
  { term: "Sustancia (Substance)", definition: "En el lenguaje constitucional, recursos o riqueza. La queja de la Declaración sobre oficiales enviados 'a devorar su sustancia' se refiere a funcionarios que drenaban el dinero y los recursos de los colonos." },

  // === T ===
  { term: "Teoría del derecho (Jurisprudence)", definition: "La teoría y filosofía del derecho, o el conjunto de decisiones judiciales sobre un tema. 'La jurisprudencia de la Primera Enmienda' son todos los fallos que moldean la libertad de expresión." },
  { term: "Testimonio (Testimony)", definition: "Una declaración formal, usualmente bajo juramento, ante un tribunal o cuerpo legislativo. Dar falso testimonio es perjurio, un delito." },
  { term: "Testimonio de oídas (Hearsay)", definition: "Una declaración hecha fuera del tribunal ofrecida como evidencia. Generalmente inadmisible porque quien la hizo no está presente para ser contrainterrogado." },
  { term: "Tiranía (Tyranny)", definition: "Gobierno cruel y opresivo. Los Fundadores diseñaron la separación de poderes y los pesos y contrapesos específicamente para prevenir la tiranía." },
  { term: "Traición (Treason)", definition: "Traicionar a Estados Unidos haciéndole la guerra o dando ayuda y auxilio a sus enemigos. La Constitución la define de forma estrecha y exige dos testigos del mismo acto manifiesto." },
  { term: "Tranquilidad doméstica (Domestic Tranquility)", definition: "La paz dentro del país. El Preámbulo lista 'asegurar la tranquilidad doméstica' (mantener la paz interna) como propósito central del gobierno." },
  { term: "Tratado (Treaty)", definition: "Un acuerdo formal entre naciones. El Presidente negocia los tratados, pero deben ser aprobados por 2/3 de los senadores presentes para entrar en vigor." },
  { term: "Tribunal de inmigración (Immigration Court)", definition: "Un tribunal dentro del Departamento de Justicia (parte del poder ejecutivo, no del judicial) donde los jueces de inmigración deciden casos de deportación y solicitudes de alivio como el asilo. Puede tener un abogado a su propio costo, pero el gobierno no le proporciona uno. Las decisiones pueden apelarse ante la Junta de Apelaciones de Inmigración y luego ante un tribunal federal de apelaciones." },

  // === U ===
  { term: "Unalienable", definition: "Grafía arcaica de 'inalienable' usada en la Declaración: que no puede quitarse, cederse ni transferirse. Los derechos a la vida, la libertad y la búsqueda de la felicidad son unalienable." },
  { term: "Usurpación (Usurpation)", definition: "Tomar el poder ilegalmente o sin autoridad. La Declaración describe una 'larga serie de abusos y usurpaciones': el Rey seguía tomando poder que no era suyo." },

  // === V ===
  { term: "Veredicto (Verdict)", definition: "La decisión formal del jurado en un juicio: culpable o no culpable en casos penales, o a favor o en contra del demandante en civiles." },
  { term: "Veto", definition: "El poder del Presidente de rechazar un proyecto de ley aprobado por el Congreso. El Congreso puede anular el veto con 2/3 de ambas cámaras." },
  { term: "Veto de bolsillo (Pocket Veto)", definition: "Una forma en que el Presidente anula un proyecto de ley al no firmarlo cuando el Congreso ha levantado sus sesiones y no puede recibir un mensaje de veto dentro del plazo de 10 días (sin contar domingos). A diferencia de un veto normal, no puede anularse; el Congreso debe aprobar el proyecto de nuevo." },
  { term: "Veto del abucheador (Heckler's Veto)", definition: "Cuando el gobierno silencia a un orador porque el público es hostil a su mensaje. Los tribunales han fallado que el gobierno no puede castigar al orador por las reacciones de su audiencia." },
  { term: "Voir Dire", definition: "El proceso de interrogar a posibles jurados para determinar si pueden ser justos e imparciales. Del francés antiguo 'decir la verdad.' Los abogados lo usan para seleccionar (o rechazar) jurados." },
  { term: "Voto concurrente (Concurrence)", definition: "Una opinión escrita por un juez que está de acuerdo con el resultado pero por razones distintas a la mayoría. Puede influir en cómo los tribunales futuros interpretan la ley." },
  { term: "Voto disidente (Dissent)", definition: "Una opinión escrita por un juez en desacuerdo con la decisión de la mayoría. No tiene fuerza legal, pero puede influir en tribunales futuros. Algunas disidencias famosas luego se volvieron ley." }
];

